boolean isValidTransition(Thread.State from, Thread.State to) {
    if (from == Thread.State.NEW) return to == Thread.State.RUNNABLE;
    if (from == Thread.State.BLOCKED || from == Thread.State.WAITING || from == Thread.State.TIMED_WAITING) return to == Thread.State.RUNNABLE;
    if (from == Thread.State.RUNNABLE) return to != Thread.State.NEW;
    return false; // TERMINATED nigdzie nie przechodzi
}
System.out.println(isValidTransition(Thread.State.NEW, Thread.State.RUNNABLE)); // true
System.out.println(isValidTransition(Thread.State.BLOCKED, Thread.State.WAITING)); // false

