class StateWatcher extends Thread {
    Thread cel; Map<Thread.State,Integer> zliczenia = new EnumMap<>(Thread.State.class);
    StateWatcher(Thread c) { cel = c; }
    public void run() {
        for (int i = 0; i < 50 && cel.getState() != Thread.State.TERMINATED; i++) {
            zliczenia.merge(cel.getState(), 1, Integer::sum);
            try { Thread.sleep(20); } catch (Exception e) {}
        }
    }
}
Thread roboczy = new Thread(() -> { try { Thread.sleep(300); } catch (Exception e) {} });
